import data from './poker-response-data.mjs';
const sum=a=>a.reduce((n,x)=>n+x,0);
function keys({street,strength,draw=0,price=0,pot=0,inPosition=false,facingRaises=0}){const owed=price>0?1:0,bucket=Math.min(7,Math.max(0,Math.floor(strength*8))),odds=Math.min(4,Math.floor(price/Math.max(1,pot+price)*10)),raises=Math.min(2,Math.max(0,facingRaises));return data.schema===2?[[street,owed,bucket,odds,inPosition?1:0,draw>0?1:0,raises].join(':'),[street,owed,bucket,raises].join(':'),[street,owed,raises].join(':')]:[[street,owed,bucket,odds,inPosition?1:0,draw>0?1:0].join(':'),[street,owed,bucket].join(':'),[street,owed].join(':')]}
function distribution(tables,ks,fallback){const g=tables[2]?.[ks[2]]??fallback,prior=g.map(x=>(x+1)/(sum(g)+3)),c=tables[1]?.[ks[1]]??[0,0,0],base=c.map((x,i)=>(x+prior[i]*12)/(sum(c)+12)),e=tables[0]?.[ks[0]]??[0,0,0];return e.map((x,i)=>(x+base[i]*16)/(sum(e)+16))}
function conditioned(f,kind){const ks=keys(f),action=kind==='action',pooled=distribution(action?[data.exact,data.coarse,data.global]:[data.sizes,data.coarseSizes,data.globalSizes],ks,action?(f.price>0?[2,5,1]:[0,5,1]):[3,4,2]);if(!Number.isInteger(f.publicStyle)||f.publicStyle<0||f.publicStyle>8)return pooled;
 const tables=action?[data.styleExact,data.styleCoarse,data.styleGlobal]:[data.styleSizes,data.styleCoarseSizes,data.styleGlobalSizes],styleKeys=ks.map(k=>f.publicStyle+':'+k),g=tables[2]?.[styleKeys[2]]??[0,0,0],prior=g.map((x,i)=>(x+pooled[i]*20)/(sum(g)+20)),c=tables[1]?.[styleKeys[1]]??[0,0,0],base=c.map((x,i)=>(x+prior[i]*12)/(sum(c)+12)),e=tables[0]?.[styleKeys[0]]??[0,0,0];return e.map((x,i)=>(x+base[i]*20)/(sum(e)+20));
}
const mixtureCache=new Map();
export const mixtureCacheSize=()=>mixtureCache.size;
function mixed(f,kind){const w=f.styleBelief;if(!w||!Array.isArray(w.weights)||w.weights.length!==9||!w.weights.every(x=>Number.isFinite(x)&&x>=0)||Math.abs(sum(w.weights)-1)>1e-6)return conditioned(f,kind);const confidence=Number.isFinite(w.confidence)?Math.max(0,Math.min(.8,w.confidence)):0,key=JSON.stringify([kind,keys(f)[0],w.weights,confidence]);if(mixtureCache.has(key))return mixtureCache.get(key).slice();const base=conditioned({...f,publicStyle:undefined},kind),out=base.map(x=>x*(1-confidence));for(let i=0;i<9;i++)if(w.weights[i]>0){const p=conditioned({...f,publicStyle:i},kind);for(let k=0;k<3;k++)out[k]+=confidence*w.weights[i]*p[k]}mixtureCache.set(key,out.slice());while(mixtureCache.size>512)mixtureCache.delete(mixtureCache.keys().next().value);return out}
export function responseRates(f){let out=mixed(f,'action');if(!(f.price>0)){out[1]+=out[0];out[0]=0}return out}
export function raiseSizeRates(f){return mixed(f,'size')}
export const responseTraining={hands:data.trainedHands,supplementalPositions:data.supplementalPositions??0,observations:data.observations,contexts:data.contexts??{}};
